    def fmt(vals, k):
        return str(len(vals)) + '\n' + ' '.join(map(str, vals)) + '\n' + str(k)
    tests = [fmt([42], 1), fmt([1, 2], 1), fmt([1, 2], 2), fmt([7, 8, 9], 3), fmt([7, 8, 9], 1), fmt([7, 7, 7], 2),
             fmt([10, 20, 30, 40, 50], 2), fmt([-5, 0, 5], 2)]
    for n in (2, 3, 4, 5, 6, 8, 10, 15, 20, 30):
        for _ in range(2):
            vals = [rng.randint(-20, 20) for _ in range(n)]
            tests.append(fmt(vals, rng.randint(1, n)))
    N = 100000
    def big():
        return [rng.randint(-10**5, 10**5) for _ in range(N)]
    tests.append(fmt(big(), 1))
    tests.append(fmt(big(), N))
    tests.append(fmt(big(), N // 2))
    tests.append(fmt(big(), rng.randint(1, N)))
    return tests

