    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            values[i] = (int) in.nval;
        }
        in.nextToken();
        int k = (int) in.nval;
        int[][] res = removeKthFromEnd(values, k);
        StringBuilder sb = new StringBuilder();
        sb.append(res[0][0]).append("\n");
        if (res[1].length == 0) {
            sb.append("empty\n");
        } else {
            for (int i = 0; i < res[1].length; i++) sb.append(res[1][i]).append(i + 1 < res[1].length ? " " : "\n");
        }
        System.out.print(sb);
    }
